import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile = await mkdtemp(path.join(os.tmpdir(), 'legendgirl-som-chrome-'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', '--mute-audio', '--no-first-run', '--no-default-browser-check', '--autoplay-policy=no-user-gesture-required', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++) { try { port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break; } catch {} await new Promise(r=>setTimeout(r,100)); }
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await (await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};

 const output='docs/diario-ia/qa-resultados/menina-ilustrada';await mkdir(output,{recursive:true});const results=[];
 for(const [name,width,height,mobile]of [['desktop',960,540,false],['android',390,844,true],['paisagem',844,390,true]]){
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile});await call('Emulation.setUserAgentOverride',{userAgent:mobile?'Mozilla/5.0 (Linux; Android 14) Mobile':'Mozilla/5.0 (Macintosh)'});
  await call('Page.navigate',{url:'http://127.0.0.1:3000/tests/dark-room-playthrough.html'});let ready=false;for(let i=0;i<300;i++){if(await evaluate('Boolean(window.review)')){ready=true;break;}await new Promise(r=>setTimeout(r,100));}assert.ok(ready,'Jogo e recursos novos carregados');
  await evaluate(`(async()=>{window.qa=await import('/docs/diario-ia/qa/menina-ilustrada-20261023/cenario.js');})()`);
  const report=await evaluate('qa.audit()');results.push({name,...report});
  for(const [label,expression]of [['pegadas','qa.carryingGallery()'],['poses','qa.poseGallery()'],['sala','qa.roomShot()']]){
   const bytes=Buffer.from(await evaluate(expression),'base64');await writeFile(output+'/'+name+'-'+label+'.png',bytes);if(name==='desktop')await writeFile('/tmp/legendgirl-menina-'+label+'.png',bytes);
  }
 }
 await writeFile(output+'/resultado.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results,null,2));console.log('APROVADO: novas poses com alfa e pés ancorados, dedos em primeiro plano nos oito brinquedos, coleta/caminhada/baú/save reais e arena sem alterar estado.');
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
